        for (int ti = 0; ti < trows; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE
            int i = it + ti;

            // Scale lower-triangular part by beta.
            for (int j = 0; j <= i; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
